    @EventHandler( payloadType=CreateWarehouseEvent.class )
    public void handle( CreateWarehouseEvent event) {
	    LOGGER.info("handling CreateWarehouseEvent - " + event );
	    Warehouse entity = new Warehouse();
            entity.setWarehouseId( event.getWarehouseId() );
            entity.setName( event.getName() );
            entity.setCode( event.getCode() );
            entity.setAddress( event.getAddress() );
            entity.setTimeZone( event.getTimeZone() );
            entity.setAllowsOverAllocation( event.getAllowsOverAllocation() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllWarehouse( entity );
    }

