    /**
     * Method to retrieve the Warehouse via an WarehousePrimaryKey.
     * @param 	id Long
     * @return 	Warehouse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Warehouse handle( FindWarehouseQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getWarehouseId() );
    }
    
    /**
     * Method to retrieve a collection of all Warehouses
     *
     * @param	query	FindAllWarehouseQuery 
     * @return 	List<Warehouse> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Warehouse> handle( FindAllWarehouseQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindWarehouse,
 * but only if the id matches
 *
 * @param		entity	Warehouse
 */
	protected void emitFindWarehouse( Warehouse entity ) {
		LOGGER.info("handling emitFindWarehouse" );
		
	    queryUpdateEmitter.emit(FindWarehouseQuery.class,
	                            query -> query.getFilter().getWarehouseId().equals(entity.getWarehouseId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllWarehouse
	 * 
	 * @param		entity	Warehouse
	 */
	protected void emitFindAllWarehouse( Warehouse entity ) {
		LOGGER.info("handling emitFindAllWarehouse" );
		
	    queryUpdateEmitter.emit(FindAllWarehouseQuery.class,
	                            query -> true,
	                            entity);
	}

